  assert.equal(r.stdout, JSON.stringify(JSON.parse(text), null, 2) + '\n');
  assert.equal(r.code, 0);
  assert.deepEqual(run([file('p00.json', '[]')], ''), { code: 3, stdout: '', stderr: 'Error: stdin: invalid JSON\n' });
});

